import{_ as a,o as t,c as i,an as s}from"./chunks/framework.NceSQmrg.js";const h=JSON.parse('{"title":"Worked examples","description":"","frontmatter":{},"headers":[],"relativePath":"worked-examples.md","filePath":"worked-examples.md","lastUpdated":null}'),o={name:"worked-examples.md"};function r(l,e,n,d,p,c){return t(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="Worked-examples" tabindex="-1">Worked examples <a class="header-anchor" href="#Worked-examples" aria-label="Permalink to &quot;Worked examples {#Worked-examples}&quot;">​</a></h1><p>These pages turn the former Quarto notebooks into a guided tour of model authoring with StanBlocks. Runnable examples are evaluated during the documentation build: the Julia source shown on a page is the exact source that produced the complete Stan program shown with it.</p><h2 id="How-to-read-the-executable-examples" tabindex="-1">How to read the executable examples <a class="header-anchor" href="#How-to-read-the-executable-examples" aria-label="Permalink to &quot;How to read the executable examples {#How-to-read-the-executable-examples}&quot;">​</a></h2><p>Every generated example uses the same presentation as the <a href="./feature-atlas">feature atlas</a>: 2. read the model in the <strong>StanBlocks</strong> tab;</p><ol start="3"><li><p>switch to <strong>Generated Stan</strong> to inspect the complete emitted program; or</p></li><li><p>choose <strong>Compare side by side</strong> for a wide modal with both versions.</p></li></ol><p>Family pages evaluate one source block and label every resulting Stan program. Nothing asks the reader to run Julia in order to see the output. The prose before each block explains the statistical progression and calls out the DSL features that make it possible.</p><h2 id="Model-families" tabindex="-1">Model families <a class="header-anchor" href="#Model-families" aria-label="Permalink to &quot;Model families {#Model-families}&quot;">​</a></h2><ul><li><p><a href="./examples/golf-models">Golf models</a> progresses from logistic regression to geometry-based putting models, residual variation, and estimated physical tolerances. It highlights <code>Base.merge</code>, inferred declarations, and ordinary Julia preprocessing.</p></li><li><p><a href="./examples/isba-2024">PCR sensitivity versus time</a> builds a 5×2 family from five latent-time structures and two link functions. It highlights <code>@deffun</code>, higher-order dispatch, varargs, custom likelihoods, and recursive model-family construction.</p></li><li><p><a href="./examples/crowdsource">Crowdsourced ratings</a> builds a latent-truth/rater model and 18 restrictions of it. It highlights custom likelihood families, generated checks, and post-hoc component replacement.</p></li><li><p><a href="./examples/constraints">Reusable constraints</a> covers a disk transform and ten simplex transforms. It highlights named-tuple returns, function-valued arguments, custom parameter-introducing distributions, and Jacobian terms.</p></li></ul><h2 id="Case-studies" tabindex="-1">Case studies <a class="header-anchor" href="#Case-studies" aria-label="Permalink to &quot;Case studies {#Case-studies}&quot;">​</a></h2><ul><li><p><a href="./examples/case-studies/golf">Golf putting</a> — composition through reusable probability submodels.</p></li><li><p><a href="./examples/case-studies/motorcycle">Motorcycle data</a> — a Hilbert-space GP component reused for both the mean and log scale.</p></li><li><p><a href="./examples/case-studies/radon">Multilevel radon regression</a> — complete, no, and partial pooling plus the CV marker.</p></li><li><p><a href="./examples/case-studies/planets">Planetary motion</a> — the original forward simulator, <code>k</code>-only inverse problem, and full unknown-star ODE model.</p></li><li><p><a href="./examples/case-studies/school">Disease transmission</a> — an SIR system with prevalence, incidence, and under-reported-incidence observation models.</p></li><li><p><a href="./examples/case-studies/species">Multiple species-site occupancy</a> — the original discrete-state-marginalized occupancy likelihood and generated abundance quantities.</p></li><li><p><a href="./examples/case-studies/soil">Soil carbon</a> — a two-pool feedback ODE reused by direct-residual and latent measurement-error observation models.</p></li><li><p><a href="./examples/monster">Monster pharmacokinetics</a> — a four-compartment PBPK model expressed both directly in StanBlocks and through BRM&#39;s named subject-level formula predictors and group-local kernel.</p></li></ul><h2 id="Maintained-implementation-references" tabindex="-1">Maintained implementation references <a class="header-anchor" href="#Maintained-implementation-references" aria-label="Permalink to &quot;Maintained implementation references {#Maintained-implementation-references}&quot;">​</a></h2><ul><li><a href="./examples/posteriordb-implementations">PosteriorDB implementations</a> inventories the 77 current optional-extension models and explains how the catalogue is organized without duplicating its maintained source file.</li></ul><h2 id="Design-and-historical-material" tabindex="-1">Design and historical material <a class="header-anchor" href="#Design-and-historical-material" aria-label="Permalink to &quot;Design and historical material {#Design-and-historical-material}&quot;">​</a></h2><ul><li><p><a href="./examples/slic-overview">The original <code>@slic</code> design overview</a></p></li><li><p><a href="./examples/simplex-transforms">Simplex transform experiments</a></p></li></ul><p>These historical pages are curated records rather than raw dumps: each says what the experiment was trying to demonstrate, which parts correspond to current StanBlocks features, and where the original exploration intentionally stopped.</p>',15)])])}const u=a(o,[["render",r]]);export{h as __pageData,u as default};
